[CmdletBinding()]
param()
$root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path
$scripts=@('install.ps1','install-dev.ps1','check-prerequisites.ps1','setup-backend.ps1','setup-frontend.ps1','setup-database.ps1','start-dev.ps1','start-production.ps1','build-windows.ps1','test-all.ps1','verify-installation.ps1','update.ps1','backup.ps1','restore.ps1','uninstall.ps1','clean.ps1')
$rows=@('# Installation Validation Matrix','',"Generated by Windows CI at $(Get-Date -Format o).",'','| Script | Syntaxe | Exécution | Tests d’erreur | Résultat | Statut |','|---|---|---|---|---|---|')
foreach($name in $scripts){$syntax='Réussie (CI Windows)';$execution=if($name -in @('setup-database.ps1','build-windows.ps1','test-all.ps1','verify-installation.ps1')){'Réussie'}else{'Non exécutée en CI'};$error=if($name -eq 'restore.ps1'){'Réussi'}else{'Statique uniquement'};$status=if($execution -eq 'Réussie'){'Validé CI'}else{'Partiel'};$rows+="| $name | $syntax | $execution | $error | Voir logs CI | $status |"}
$rows|Set-Content -Encoding UTF8 (Join-Path $root 'INSTALLATION_VALIDATION_MATRIX.md')
